def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "offer_seat": And([
            self.elder_detected,
            self.seat_available,
            Not(self.person_acknowledged(self.elder)),
            self.robot_has_vision,
            self.robot_has_badge_reader
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
